389	// CloseShift 结束班次。任一接班交接存在未确认接收的事项（待处理、退回、
390	// 处理结果缺失或无法识别）时不允许结束，其他交接已完成也不能放行；空清单
391	// 交接视为已完成，可以结束。
392	// 结束成功时把在班事项（本班新增与已接收，含结束前已关闭者）冻结为结束时记录；
393	// 校验或保存失败时不留下任何记录，班次保持进行中，也不改变交接结果、
394	// 事项归属与已保存的处理经过。
395	// 只有本地数据保存成功才算结束完成：写盘失败时内存变更随快照一并回滚，
396	// 保留原保存错误并返回零值班次（无编号、无结束状态、无结束时间、无结束时
397	// 事项记录，空清单班次同样如此），不把尚未保存的结束状态或失败前查询到的
398	// 进行中班次当作结束结果返回。
399	// 返回的班次结果是成功结束时的独立副本（关闭时间与结束时记录均深拷贝）：
400	// 调用方为本地展示改动结果（实际结束时刻、事项内容、清单项、关闭时间等）
401	// 只影响手中的结果，不改变系统保存的结束时事实，也不随之后的正常保存被带进
402	// 存储；先取得的另一份结果同样互不影响。
403	func (svc *Service) CloseShift(shiftID string) (Shift, error) {
404		shiftID = clean(shiftID)
405		var result Shift
406		err := svc.store.mutate(func(d *Data) error {
407			sh, _ := findShift(d, shiftID)
408			if sh == nil {
409				return fmt.Errorf("%w：班次 %s", ErrNotFound, shiftID)
410			}
411			if sh.Closed {
412				return fmt.Errorf("%w：班次 %s 已结束", ErrShiftClosed, sh.ID)
413			}
414			for i := range d.Handovers {
415				h := &d.Handovers[i]
416				if h.ToShiftID == sh.ID && !h.Completed() {
417					return fmt.Errorf("%w：接班交接 %s 仍有未确认接收的事项，班次不能结束",
418						ErrHandoverState, h.ID)
419				}
420			}
421			now := svc.now()
422			sh.Closed = true
423			sh.ClosedAt = &now
424	
425			// 冻结结束时在班的全部事项。退回或未确认的交接事项当前班次仍在交班
426			// 班次，不会被快照；结束前已关闭的事项保留关闭人与关闭时间。每项指针
427			// （关闭时间）都复制一份：结束时记录保留这次成功结束时的事实，既不与
428			// 事项当前记录共享内存，也不与交给调用方的结果共享内存。
429			record := &ShiftCloseRecord{Items: []CloseItemSnapshot{}}
430			for i := range d.Items {
431				it := &d.Items[i]
432				if it.CurrentShiftID != sh.ID {
433					continue
434				}
435				record.Items = append(record.Items, CloseItemSnapshot{
436					ItemID:        it.ID,
437					Content:       it.Content,
438					Severity:      it.Severity,
439					Constraints:   it.Constraints,
440					FollowOwner:   it.FollowOwner,
441					Closed:        it.Closed,
442					ClosedAt:      cloneTimePtr(it.ClosedAt),
443					CloseOperator: it.CloseOperator,
444				})
445			}
446			sort.Slice(record.Items, func(i, j int) bool { return record.Items[i].ItemID < record.Items[j].ItemID })
447			sh.CloseRecord = record
448	
449			// 返回独立副本：调用方改写自己保留的结果不能影响系统保存的结束时记录。
450			result = cloneShift(*sh)
451			return nil
452		})
453		if err != nil {
454			// 业务拒绝或保存失败时不返回任何班次结果：保存失败时内存已回滚，
455			// 不能把尚未保存的结束状态当作结束结果交给调用方。
456			return Shift{}, err
457		}
458		return result, nil
459	}
