12	// 本文件为“首次发起交接在本地数据保存阶段失败”的可重复回归保障：交班班次
13	// 已经结束、接班班次符合首次发起的现有条件、交班班次此前没有发起交接，业务
14	// 校验全部通过、真正进入保存过程后本地写盘失败。此时发起操作必须返回原保存
15	// 错误与零值交接结果，不能把尚未保存的编号、发起时间、清单（空清单交接还
16	// 包括完成时间）当作发起结果交给调用方；系统内不留下这次交接的任何一部分，
17	// 失败尝试不占用交接编号，也不留下已指定接班对象的关系。沿用既有保存失败
18	// 测试的同一套故障注入方式（在 .tmp 路径放目录使写入必然失败）。
19	
20	// failedCreateExpectations 汇总失败尝试发生前已保存的业务事实，供 reopen
21	// 前后用同一组期望核对。
22	type failedCreateExpectations struct {
23		fromShift, toShift string
24		idA, idB           string // 交班班次结束时的未关闭事项（应进入清单但未保存）
25		closedID           string // 交班班次结束前已关闭的事项
26		failAt             time.Time
27	}
28	
29	// assertZeroHandoverResult 核对发起操作返回的是零值交接结果：编号、岗位和
30	// 两班编号为空，发起时间为零值，完成时间为空，清单没有事项。
31	func assertZeroHandoverResult(t *testing.T, got Handover) {
32		t.Helper()
33		if got.ID != "" || got.Position != "" || got.FromShiftID != "" || got.ToShiftID != "" {
34			t.Fatalf("保存失败不得返回未保存的编号、岗位或两班编号：%+v", got)
35		}
36		if !got.CreatedAt.IsZero() {
37			t.Fatalf("保存失败不得返回未保存的发起时间：%+v", got.CreatedAt)
38		}
39		if got.CompletedAt != nil {
40			t.Fatalf("保存失败不得返回完成时间（空清单交接同样如此）：%+v", got.CompletedAt)
41		}
42		if len(got.Entries) != 0 {
43			t.Fatalf("保存失败不得返回未保存的清单：%+v", got.Entries)
44		}
45		if !reflect.DeepEqual(got, Handover{}) {
46			t.Fatalf("保存失败应返回零值交接结果：%+v", got)
47		}
48	}
49	
50	// assertNoHandoverAfterFailedCreate 用当前打开的数据核对：失败的发起没有
51	// 留下任何交接事实——交接列表与班次报告中都没有为这个交班班次建立交接，
52	// 事项留在原班次，交班班次的结束时记录保持原样。
53	func assertNoHandoverAfterFailedCreate(t *testing.T, f *fixture, w failedCreateExpectations) {
54		t.Helper()
55	
56		// 交接列表中没有为这个交班班次建立的交接；失败尝试不占用的编号查不到记录。
57		if hs := f.svc.ListHandovers(); len(hs) != 0 {
58			t.Fatalf("保存失败后不应存在任何交接记录：%+v", hs)
59		}
60		if _, err := f.svc.GetHandover("H001"); !errors.Is(err, ErrNotFound) {
61			t.Fatalf("失败尝试不占用的交接编号应查不到记录，got %v", err)
62		}
63	
64		// 交班班次报告：没有交班对象，没有各项交接当前结果；结束时记录保持原样
65		// （未关闭事项当时未关闭、已关闭事项保留关闭人与关闭时间）。
66		repFrom, err := f.svc.ShiftReport(w.fromShift)
67		if err != nil {
68			t.Fatalf("report from shift: %v", err)
69		}
70		if repFrom.Outgoing != nil {
71			t.Fatalf("交班班次报告不应出现交班对象：%+v", repFrom.Outgoing)
72		}
73		if len(repFrom.Incoming) != 0 || len(repFrom.Results) != 0 {
74			t.Fatalf("交班班次报告不应出现任何交接结果：incoming=%+v results=%+v",
75				repFrom.Incoming, repFrom.Results)
76		}
77		if !repFrom.ItemsAtClose {
78			t.Fatalf("交班班次原有结束时记录不应受失败尝试影响")
79		}
80		snapA := findCloseItem(repFrom, w.idA)
81		if snapA == nil || snapA.Closed || snapA.Content != "事项甲" || snapA.FollowOwner != "李四" {
82			t.Fatalf("交班班次结束时记录应保持原样：%+v", snapA)
83		}
84		snapClosed := findCloseItem(repFrom, w.closedID)
85		if snapClosed == nil || !snapClosed.Closed || snapClosed.CloseOperator != "张三" {
86			t.Fatalf("已关闭事项的结束时记录应保持原样：%+v", snapClosed)
87		}
88		if text := FormatReport(repFrom); !strings.Contains(text, "（尚未发起交接）") {
89			t.Fatalf("交班班次报告应显示尚未发起交接：\n%s", text)
90		}
91	
92		// 接班班次报告：没有接班交接。
93		repTo, err := f.svc.ShiftReport(w.toShift)
94		if err != nil {
95			t.Fatalf("report to shift: %v", err)
96		}
97		if len(repTo.Incoming) != 0 || repTo.Outgoing != nil || len(repTo.Results) != 0 {
98			t.Fatalf("接班班次报告不应出现任何交接：%+v", repTo)
99		}
100	
101		// 事项留在原班次，不增加流经班次，历史中没有发起交接。
102		for _, id := range []string{w.idA, w.idB} {
103			it, err := f.svc.GetItem(id)
104			if err != nil {
105				t.Fatalf("get item %s: %v", id, err)
106			}
107			if it.CurrentShiftID != w.fromShift || len(it.ShiftIDs) != 1 || it.ShiftIDs[0] != w.fromShift {
108				t.Fatalf("事项 %s 应留在原班次 %s：%+v", id, w.fromShift, it)
109			}
110			j, err := f.svc.ItemJourney(id)
111			if err != nil {
112				t.Fatalf("journey %s: %v", id, err)
113			}
114			if j.HasHandovers || len(j.Results) != 0 {
115				t.Fatalf("事项 %s 不应有任何交接记录：%+v", id, j.Results)
116			}
117			if got := joinStrings(journeyKinds(j)); got != "created" {
118				t.Fatalf("事项 %s 的处理经过应只有建立，没有发起交接，got %s", id, got)
119			}
120			for _, ev := range j.Events {
121				if ev.TimeKnown && ev.At.Equal(w.failAt) {
122					t.Fatalf("失败尝试时刻 %s 不应出现在处理经过：%+v", w.failAt, ev)
123				}
124			}
125			if text := FormatItemJourney(j); !strings.Contains(text, "暂无交接记录") {
126				t.Fatalf("事项 %s 的处理经过应显示暂无交接记录：\n%s", id, text)
127			}
128		}
129	}
