131	// TestCreateHandoverSaveFailureAtomicRollback：首次发起交接（清单含未关闭
132	// 事项）时输入与班次状态均合法，实际进入保存阶段后写盘失败——发起操作必须
133	// 返回原保存错误与零值交接结果；内存与磁盘都回到失败前：没有为这个交班班次
134	// 建立交接，事项留在原班次，结束时记录与其他数据不受影响，失败尝试不占用
135	// 交接编号、不留下已指定接班对象的关系。保存恢复后重新发起成功，取得 H001
136	// 与待处理清单，返回内容与随后的查询一致；重复发起、接班班次结束后重复发起
137	// 与改换接班对象的既有规则保持不变。
138	func TestCreateHandoverSaveFailureAtomicRollback(t *testing.T) {
139		f := newFixture(t)
140		a, b, items := prepareHandover(t, f)
141		idA, idB, idC := items[0].ID, items[1].ID, items[2].ID // 事项甲、事项乙（事项丙已关闭）
142	
143		// 另一个确实存在的同岗位接班候选，用于验证失败尝试不留下接班对象关系。
144		c := mustShift(t, f, "调度", "王五", tsDay(3, 0, 0), tsDay(3, 8, 0), "")
145	
146		want := failedCreateExpectations{
147			fromShift: a.ID, toShift: b.ID,
148			idA: idA, idB: idB, closedID: idC,
149			failAt: tsDay(2, 17, 0),
150		}
151	
152		// 记录失败前已落盘的文件内容，并固定失败尝试的发起时刻。
153		rawBefore, err := os.ReadFile(f.store.Path())
154		if err != nil {
155			t.Fatalf("read data file: %v", err)
156		}
157		f.svc.nowAt(func() time.Time { return want.failAt })
158	
159		// 交班班次已结束、接班班次符合条件、此前没有发起交接；使下一次写盘在
160		// 原子保存阶段失败。
161		breakSaving(t, f)
162		got, err := f.svc.CreateHandover(a.ID, b.ID)
163		if err == nil {
164			t.Fatalf("保存失败时发起交接应明确返回错误，不能返回新交接记录")
165		}
166		if !strings.Contains(err.Error(), "写入数据文件失败") {
167			t.Fatalf("应明确返回保存阶段的错误并保留原错误信息，got %v", err)
168		}
169		// 输入与班次状态均合法，不能改报成班次不符合条件、已经存在交接或其他
170		// 业务拒绝。
171		for _, sentinel := range []error{
172			ErrInvalidInput, ErrNotFound, ErrShiftClosed, ErrShiftNotClosed,
173			ErrHandoverExists, ErrHandoverTarget, ErrHandoverState,
174			ErrPositionMismatch, ErrSameShift, ErrOverlap,
175		} {
176			if errors.Is(err, sentinel) {
177				t.Fatalf("保存失败不应被报告为业务校验错误 %v，got %v", sentinel, err)
178			}
179		}
180		// 调用方不应取得看似已经建立的记录：编号、岗位、两班编号、发起时间、
181		// 完成时间与清单都必须是零值。
182		assertZeroHandoverResult(t, got)
183	
184		// 当前打开的数据上查看，应看到失败前的事实，而不是只保证文件没变、
185		// 查询却显示已经建立交接。
186		assertNoHandoverAfterFailedCreate(t, f, want)
187	
188		// 失败尝试不留下已指定接班对象的关系：保存仍失败时改向另一个确实存在
189		// 的接班班次发起，得到的仍是保存失败，而不是“不能改换接班对象”或
190		// “已经存在交接”。
191		if _, err := f.svc.CreateHandover(a.ID, c.ID); err == nil ||
192			errors.Is(err, ErrHandoverTarget) || errors.Is(err, ErrHandoverExists) ||
193			!strings.Contains(err.Error(), "写入数据文件失败") {
194			t.Fatalf("失败尝试不应留下接班对象关系，改向其他班次发起应仍是保存失败，got %v", err)
195		}
196	
197		// 失败前已保存的数据文件一个字节都不应改变（原子改名未发生）。
198		rawAfter, err := os.ReadFile(f.store.Path())
199		if err != nil {
200			t.Fatalf("read data file after failure: %v", err)
201		}
202		if string(rawAfter) != string(rawBefore) {
203			t.Fatalf("保存失败不得改动既有数据文件，失败的发起不能成为其中的业务事实")
204		}
205	
206		// 退出后重新打开：仍没有为这个交班班次建立交接。
207		f.reopen(t)
208		assertNoHandoverAfterFailedCreate(t, f, want)
209	
210		// 保存恢复正常后重新发起：按现有功能成功，失败尝试不占用交接编号。
211		restoreSaving(t, f)
212		successAt := tsDay(2, 18, 0)
213		f.svc.nowAt(func() time.Time { return successAt })
214		h, err := f.svc.CreateHandover(a.ID, b.ID)
215		if err != nil {
216			t.Fatalf("恢复后发起交接应成功：%v", err)
217		}
218		if h.ID != "H001" {
219			t.Fatalf("失败尝试不应占用交接编号，成功发起应取得 H001，got %s", h.ID)
220		}
221		if h.Position != "调度" || h.FromShiftID != a.ID || h.ToShiftID != b.ID {
222			t.Fatalf("成功发起的岗位与两班关系不正确：%+v", h)
223		}
224		if !h.CreatedAt.Equal(successAt) {
225			t.Fatalf("发起时间应以本次成功发起为准：%+v", h.CreatedAt)
226		}
227		if h.Completed() || h.CompletedAt != nil {
228			t.Fatalf("有事项的清单初始为待处理，交接不应完成：%+v", h)
229		}
230		if len(h.Entries) != 2 {
231			t.Fatalf("清单应包含两项未关闭事项，got %d：%+v", len(h.Entries), h.Entries)
232		}
233		for _, e := range h.Entries {
234			if e.ItemID == idC {
235				t.Fatalf("已关闭事项不应进入清单：%+v", e)
236			}
237			if e.Status != EntryPending || e.Operator != "" || e.ProcessedAt != nil {
238				t.Fatalf("清单项初始应为待处理、尚未处理：%+v", e)
239			}
240		}
241	
242		// 返回内容应与随后的查询一致。
243		queried, err := f.svc.GetHandover(h.ID)
244		if err != nil {
245			t.Fatalf("get handover after success: %v", err)
246		}
247		if !reflect.DeepEqual(h, queried) {
248			t.Fatalf("发起返回内容应与随后查询一致：\n返回 %+v\n查询 %+v", h, queried)
249		}
250	
251		// 保留已有的重复发起行为：返回原记录及交接已存在错误标识。
252		dup, err := f.svc.CreateHandover(a.ID, b.ID)
253		if !errors.Is(err, ErrHandoverExists) || dup.ID != h.ID {
254			t.Fatalf("重复发起应返回原记录及 ErrHandoverExists，got %v id=%s", err, dup.ID)
255		}
256		if !reflect.DeepEqual(dup, queried) {
257			t.Fatalf("重复发起应返回保存的原记录：\n返回 %+v\n原记录 %+v", dup, queried)
258		}
259	
260		// 改换接班对象仍按现有规则明确拒绝。
261		if _, err := f.svc.CreateHandover(a.ID, c.ID); !errors.Is(err, ErrHandoverTarget) {
262			t.Fatalf("改换接班对象应报 ErrHandoverTarget，got %v", err)
263		}
264	
265		// 接班班次后来已经结束也一样：逐项接收后结束接班班次，重复发起仍返回
266		// 原记录，不能把原记录清空或重新建立交接。
267		f.svc.nowAt(func() time.Time { return tsDay(2, 19, 0) })
268		for _, id := range []string{idA, idB} {
269			if _, err := f.svc.ProcessEntry(h.ID, id, ActionConfirm, "李四", "", "", ""); err != nil {
270				t.Fatalf("confirm %s: %v", id, err)
271			}
272		}
273		if _, err := f.svc.CloseShift(b.ID); err != nil {
274			t.Fatalf("全部接收后接班班次应能结束：%v", err)
275		}
276		saved, err := f.svc.GetHandover(h.ID)
277		if err != nil {
278			t.Fatalf("get handover after receiver closed: %v", err)
279		}
280		dup2, err := f.svc.CreateHandover(a.ID, b.ID)
281		if !errors.Is(err, ErrHandoverExists) || dup2.ID != h.ID {
282			t.Fatalf("接班班次结束后重复发起应返回原记录及 ErrHandoverExists，got %v id=%s", err, dup2.ID)
283		}
284		if !reflect.DeepEqual(dup2, saved) {
285			t.Fatalf("接班班次结束后重复发起不应清空或重建原记录：\n返回 %+v\n原记录 %+v", dup2, saved)
286		}
287		if hs := f.svc.ListHandovers(); len(hs) != 1 || hs[0].ID != h.ID {
288			t.Fatalf("应仍只有成功保存的那一份交接：%+v", hs)
289		}
290	}
291	
292	// TestCreateHandoverSaveFailureEmptyListAtomicRollback：空清单的首次交接
293	// 同样遵守保存失败规则——保存失败后返回原保存错误与零值交接结果（完成时间
294	// 也为空，不能把未保存的“发起时完成”当作结果）；系统内不留下交接。保存
295	// 恢复后重新发起成功，空清单在发起时完成，返回内容与随后查询一致。
296	func TestCreateHandoverSaveFailureEmptyListAtomicRollback(t *testing.T) {
