299		b := mustShift(t, f, "调度", "李四", tsDay(2, 16, 0), tsDay(2, 23, 0), "")
300		if _, err := f.svc.CloseShift(a.ID); err != nil {
301			t.Fatalf("空清单应能结束班次：%v", err)
302		}
303	
304		rawBefore, err := os.ReadFile(f.store.Path())
305		if err != nil {
306			t.Fatalf("read data file: %v", err)
307		}
308		failAt := tsDay(2, 17, 0)
309		f.svc.nowAt(func() time.Time { return failAt })
310	
311		breakSaving(t, f)
312		got, err := f.svc.CreateHandover(a.ID, b.ID)
313		if err == nil {
314			t.Fatalf("保存失败时空清单发起应明确返回错误，不能返回新交接记录")
315		}
316		if !strings.Contains(err.Error(), "写入数据文件失败") {
317			t.Fatalf("应明确返回保存阶段的错误并保留原错误信息，got %v", err)
318		}
319		for _, sentinel := range []error{
320			ErrInvalidInput, ErrNotFound, ErrShiftClosed, ErrShiftNotClosed,
321			ErrHandoverExists, ErrHandoverTarget, ErrHandoverState,
322			ErrPositionMismatch, ErrSameShift, ErrOverlap,
323		} {
324			if errors.Is(err, sentinel) {
325				t.Fatalf("保存失败不应被报告为业务校验错误 %v，got %v", sentinel, err)
326			}
327		}
328		// 空清单交接也不能返回未保存的完成时间。
329		assertZeroHandoverResult(t, got)
330	
331		if hs := f.svc.ListHandovers(); len(hs) != 0 {
332			t.Fatalf("保存失败后不应存在任何交接记录：%+v", hs)
333		}
334		rep, err := f.svc.ShiftReport(a.ID)
335		if err != nil {
336			t.Fatalf("report from shift: %v", err)
337		}
338		if rep.Outgoing != nil {
339			t.Fatalf("交班班次报告不应出现交班对象：%+v", rep.Outgoing)
340		}
341		rawAfter, err := os.ReadFile(f.store.Path())
342		if err != nil {
343			t.Fatalf("read data file after failure: %v", err)
344		}
345		if string(rawAfter) != string(rawBefore) {
346			t.Fatalf("保存失败不得改动既有数据文件")
347		}
348	
349		// 退出后重新打开：仍没有交接。
350		f.reopen(t)
351		if hs := f.svc.ListHandovers(); len(hs) != 0 {
352			t.Fatalf("重开后仍不应存在交接记录：%+v", hs)
353		}
354	
355		// 保存恢复后重新发起：空清单在发起时完成，失败尝试不占用编号。
356		restoreSaving(t, f)
357		successAt := tsDay(2, 18, 0)
358		f.svc.nowAt(func() time.Time { return successAt })
359		h, err := f.svc.CreateHandover(a.ID, b.ID)
360		if err != nil {
361			t.Fatalf("恢复后空清单发起应成功：%v", err)
362		}
363		if h.ID != "H001" {
364			t.Fatalf("失败尝试不应占用交接编号，成功发起应取得 H001，got %s", h.ID)
365		}
366		if !h.Completed() || h.CompletedAt == nil || !h.CompletedAt.Equal(successAt) {
367			t.Fatalf("空清单应在发起时完成，完成时间以成功发起时刻为准：%+v", h)
368		}
369		if len(h.Entries) != 0 || !h.CreatedAt.Equal(successAt) {
370			t.Fatalf("空清单交接应没有事项，发起时间以成功发起为准：%+v", h)
371		}
372		queried, err := f.svc.GetHandover(h.ID)
373		if err != nil {
374			t.Fatalf("get handover after success: %v", err)
375		}
376		if !reflect.DeepEqual(h, queried) {
377			t.Fatalf("发起返回内容应与随后查询一致：\n返回 %+v\n查询 %+v", h, queried)
378		}
379	
380		// 空清单的重复发起同样返回原记录及交接已存在错误标识。
381		dup, err := f.svc.CreateHandover(a.ID, b.ID)
382		if !errors.Is(err, ErrHandoverExists) || dup.ID != h.ID {
383			t.Fatalf("空清单重复发起应返回原记录及 ErrHandoverExists，got %v id=%s", err, dup.ID)
384		}
385		if !reflect.DeepEqual(dup, queried) {
386			t.Fatalf("空清单重复发起应返回保存的原记录：\n返回 %+v\n原记录 %+v", dup, queried)
387		}
388	}
